class Solution {
public:
    int maxValue(std::vector<int>& nums, int k) {
        int n = nums.size();
        const int MAX_V = 128;

        std::vector<std::vector<std::vector<bool>>> left_dp(n + 1, std::vector<std::vector<bool>>(k + 1, std::vector<bool>(MAX_V, false)));
        left_dp[0][0][0] = true;
        for (int i = 0; i < n; ++i) {
            int val = nums[i];
            for (int c = 0; c <= k; ++c) {
                for (int v = 0; v < MAX_V; ++v) {
                    if (left_dp[i][c][v]) {
                        left_dp[i + 1][c][v] = true;
                        if (c + 1 <= k) left_dp[i + 1][c + 1][v | val] = true;
                    }
                }
            }
        }

        std::vector<std::vector<std::vector<bool>>> right_dp(n + 1, std::vector<std::vector<bool>>(k + 1, std::vector<bool>(MAX_V, false)));
        right_dp[n][0][0] = true;
        for (int i = n - 1; i >= 0; --i) {
            int val = nums[i];
            for (int c = 0; c <= k; ++c) {
                for (int v = 0; v < MAX_V; ++v) {
                    if (right_dp[i + 1][c][v]) {
                        right_dp[i][c][v] = true;
                        if (c + 1 <= k) right_dp[i][c + 1][v | val] = true;
                    }
                }
            }
        }

        int ans = 0;
        for (int i = k; i <= n - k; ++i) {
            std::vector<int> left_vals, right_vals;
            for (int v = 0; v < MAX_V; ++v) {
                if (left_dp[i][k][v]) left_vals.push_back(v);
                if (right_dp[i][k][v]) right_vals.push_back(v);
            }
            for (int lv : left_vals) {
                for (int rv : right_vals) {
                    ans = std::max(ans, lv ^ rv);
                }
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxValue(int[] nums, int k) {
        int n = nums.length;
        int MAX_V = 128;

        boolean[][][] leftDp = new boolean[n + 1][k + 1][MAX_V];
        leftDp[0][0][0] = true;
        for (int i = 0; i < n; i++) {
            int val = nums[i];
            for (int c = 0; c <= k; c++) {
                for (int v = 0; v < MAX_V; v++) {
                    if (leftDp[i][c][v]) {
                        leftDp[i + 1][c][v] = true;
                        if (c + 1 <= k) leftDp[i + 1][c + 1][v | val] = true;
                    }
                }
            }
        }

        boolean[][][] rightDp = new boolean[n + 1][k + 1][MAX_V];
        rightDp[n][0][0] = true;
        for (int i = n - 1; i >= 0; i--) {
            int val = nums[i];
            for (int c = 0; c <= k; c++) {
                for (int v = 0; v < MAX_V; v++) {
                    if (rightDp[i + 1][c][v]) {
                        rightDp[i][c][v] = true;
                        if (c + 1 <= k) rightDp[i][c + 1][v | val] = true;
                    }
                }
            }
        }

        int ans = 0;
        for (int i = k; i <= n - k; i++) {
            List<Integer> leftVals = new ArrayList<>();
            List<Integer> rightVals = new ArrayList<>();
            for (int v = 0; v < MAX_V; v++) {
                if (leftDp[i][k][v]) leftVals.add(v);
                if (rightDp[i][k][v]) rightVals.add(v);
            }
            for (int lv : leftVals) {
                for (int rv : rightVals) {
                    ans = Math.max(ans, lv ^ rv);
                }
            }
        }
        return ans;
    }
}

var maxValue = function(nums, k) {
    const n = nums.length;
    const MAX_V = 128;

    const leftDp = Array.from({ length: n + 1 }, () =>
        Array.from({ length: k + 1 }, () => new Uint8Array(MAX_V))
    );
    leftDp[0][0][0] = 1;
    for (let i = 0; i < n; i++) {
        const val = nums[i];
        for (let c = 0; c <= k; c++) {
            for (let v = 0; v < MAX_V; v++) {
                if (leftDp[i][c][v]) {
                    leftDp[i + 1][c][v] = 1;
                    if (c + 1 <= k) leftDp[i + 1][c + 1][v | val] = 1;
                }
            }
        }
    }

    const rightDp = Array.from({ length: n + 1 }, () =>
        Array.from({ length: k + 1 }, () => new Uint8Array(MAX_V))
    );
    rightDp[n][0][0] = 1;
    for (let i = n - 1; i >= 0; i--) {
        const val = nums[i];
        for (let c = 0; c <= k; c++) {
            for (let v = 0; v < MAX_V; v++) {
                if (rightDp[i + 1][c][v]) {
                    rightDp[i][c][v] = 1;
                    if (c + 1 <= k) rightDp[i][c + 1][v | val] = 1;
                }
            }
        }
    }

    let ans = 0;
    for (let i = k; i <= n - k; i++) {
        const leftVals = [];
        const rightVals = [];
        for (let v = 0; v < MAX_V; v++) {
            if (leftDp[i][k][v]) leftVals.push(v);
            if (rightDp[i][k][v]) rightVals.push(v);
        }
        for (const lv of leftVals) {
            for (const rv of rightVals) {
                const x = lv ^ rv;
                if (x > ans) ans = x;
            }
        }
    }
    return ans;
};
